frappe.web_form.after_load = () => {
  // ---- Brand theming -------------------------------------------------------
  // Default palette (terracotta -> saffron) matches the product brand icon /
  // splash. An HR invite for a specific company overrides it below, using the
  // colours configured on that Company (get_invite_prefill).
  const applyTheme = (primary, secondary) => {
    const root = document.documentElement;
    root.style.setProperty('--ihc-primary', primary || '#E16A2C');
    root.style.setProperty('--ihc-secondary', secondary || primary || '#F4A04A');
  };
  applyTheme('#E16A2C', '#F4A04A');

  const css = `
    body { background: #fff7ef; }
    .web-form-container { max-width: 820px; }
    .web-form-head {
      background: linear-gradient(135deg, var(--ihc-primary), var(--ihc-secondary));
      border-radius: 14px 14px 0 0; padding: 26px 28px 30px;
      box-shadow: 0 6px 18px rgba(0,0,0,.08);
    }
    .web-form-head .web-form-title h1, .web-form-head .web-form-title p { color: #fff; }
    .web-form-introduction {
      background: #fff; border-radius: 12px; padding: 14px 18px; margin-top: 14px;
      box-shadow: 0 2px 8px rgba(0,0,0,.06); color: #444;
    }
    .web-form-introduction h3 { color: var(--ihc-primary); margin-top: 0; }
    form.web-form {
      background: #fff; border: none; border-top: 4px solid var(--ihc-primary);
      border-radius: 0 0 14px 14px; box-shadow: 0 6px 22px rgba(0,0,0,.07);
      padding: 10px 24px 18px;
    }
    .form-section .section-head, .form-section .form-section-heading, .section-label {
      color: var(--ihc-primary) !important; font-weight: 600; letter-spacing: .01em;
    }
    .web-form .form-control:focus {
      border-color: var(--ihc-primary);
      box-shadow: 0 0 0 2px color-mix(in srgb, var(--ihc-primary) 22%, transparent);
    }
    .web-form a { color: var(--ihc-primary); }
    .btn-primary, .submit-btn, .btn-next {
      background: linear-gradient(135deg, var(--ihc-primary), var(--ihc-secondary)) !important;
      border: none !important; color: #fff !important; font-weight: 600;
      box-shadow: 0 3px 10px color-mix(in srgb, var(--ihc-primary) 32%, transparent);
    }
    .btn-primary:hover, .submit-btn:hover, .btn-next:hover { filter: brightness(1.05); }
    .btn-previous, .discard-btn {
      border: 1px solid var(--ihc-primary) !important; color: var(--ihc-primary) !important;
      background: #fff !important;
    }
    .slides-progress .slide-step.active .slide-step-indicator { background: var(--ihc-primary) !important; }
    .slides-progress .slide-step.step-success .slide-step-indicator { background: var(--ihc-secondary) !important; }
    .checkbox input[type=checkbox], input[type=checkbox] { accent-color: var(--ihc-primary); }
  `;
  $('<style id="ihc-onb-theme"></style>').text(css).appendTo(document.head);

  // ---- Live formatters: uppercase PAN/IFSC, strip non-digits from Aadhaar / UAN / mobile.
  const upper = (fname) => {
    const f = frappe.web_form.get_field(fname);
    if (!f) return;
    f.$input && f.$input.on('input', () => {
      const v = (f.get_value() || '').toString().toUpperCase();
      if (v !== f.get_value()) frappe.web_form.set_value(fname, v);
    });
  };
  const digits = (fname, len) => {
    const f = frappe.web_form.get_field(fname);
    if (!f) return;
    f.$input && f.$input.on('input', () => {
      let v = (f.get_value() || '').toString().replace(/\D/g, '');
      if (len && v.length > len) v = v.slice(0, len);
      if (v !== f.get_value()) frappe.web_form.set_value(fname, v);
    });
  };
  upper('pan_number');
  upper('ifsc_code');
  digits('aadhaar_number', 12);
  digits('uan_number', 12);

  // ---- Address: mirror Current -> Permanent while "same as current" is ticked.
  // Server (_normalise) re-applies on save, so this is purely live UX.
  const mirrorAddr = () => {
    if (frappe.web_form.get_value('same_as_current_address')) {
      frappe.web_form.set_value('permanent_address', frappe.web_form.get_value('current_address') || '');
    }
  };
  const sac = frappe.web_form.get_field('same_as_current_address');
  if (sac && sac.$input) sac.$input.on('change', mirrorAddr);
  const cur = frappe.web_form.get_field('current_address');
  if (cur && cur.$input) cur.$input.on('input', mirrorAddr);

  // Client-side preview check on DOB so the candidate knows before submitting.
  const dob = frappe.web_form.get_field('date_of_birth');
  if (dob && dob.$input) {
    dob.$input.on('change', () => {
      const v = dob.get_value();
      if (!v) return;
      const age = Math.floor((Date.now() - new Date(v).getTime()) / (365.25 * 24 * 3600 * 1000));
      if (age < 14) {
        frappe.msgprint({ title: __('Age check'), message: __('You appear to be under 14 — onboarding will be blocked. Please re-check the date.'), indicator: 'red' });
      } else if (age < 18) {
        frappe.msgprint({ title: __('Heads up'), message: __('You are under 18 — HR will verify the engagement complies with Adolescent Labour rules.'), indicator: 'orange' });
      }
    });
  }
  // Invited candidate? The URL carries ONLY an opaque token — exchange it
  // server-side for the prefill (name/email/role/colours) + offer-letter download.
  const tok = (frappe.utils.get_query_params() || {}).invite_token;
  if (tok) {
    // BULLETPROOF token pass-through: Frappe's query-param prefill does not
    // reliably populate HIDDEN controls, and web_form.accept() blanks any
    // field missing from the POST (data.get(fieldname, '')). Without this,
    // the submission arrives token-less, the Draft never gets absorbed, and
    // a second 'new' application is created. Set BOTH the control (covers
    // get_values() including it) and web_form.doc (survives Object.assign
    // when get_values() omits hidden controls).
    try { frappe.web_form.set_value('invite_token', tok); } catch (e) {}
    if (frappe.web_form.doc) frappe.web_form.doc.invite_token = tok;
    frappe.call({
      method: 'indian_hrms_compliance.hr.doctype.employee_onboarding_application.employee_onboarding_application.get_invite_prefill',
      args: { token: tok },
      callback: (r) => {
        const m = r.message;
        if (!m) return;
        if (m.primary_color) applyTheme(m.primary_color, m.secondary_color);
        ['first_name', 'middle_name', 'last_name', 'personal_email'].forEach((f) => {
          if (m[f] && !frappe.web_form.get_value(f)) frappe.web_form.set_value(f, m[f]);
        });
        const role = [m.target_designation, m.target_company].filter(Boolean).join(' · ');
        const dl = m.has_offer_letter
          ? `<a class=\"btn btn-sm btn-primary\" style=\"margin-left:12px;\" href=\"/api/method/indian_hrms_compliance.hr.doctype.employee_onboarding_application.employee_onboarding_application.download_offer_letter?token=${encodeURIComponent(tok)}\">${__('Download Offer Letter')}</a>`
          : '';
        const banner = `<div style=\"background:#eef6fc;border-left:4px solid #2980b9;padding:10px 14px;margin:0 0 14px;border-radius:6px;display:flex;align-items:center;flex-wrap:wrap;\"><span>${__('You are onboarding for')} <b>${frappe.utils.escape_html(role || __('your offered role'))}</b>.${m.has_offer_letter ? ' ' + __('Download your offer letter, sign it, and upload the signed copy under Documents as \'Signed Offer Letter\' (required).') : ''}</span>${dl}</div>`;
        const $host = $('.web-form-container, .web-form, form').first();
        if ($host.length) $host.prepend(banner);
      },
      error: () => {
        frappe.msgprint({ title: __('Invite link problem'), indicator: 'red', message: __('This invite link is invalid, expired, or already used. Please ask HR for a fresh link.') });
      },
    });
  }
};
